"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0708-11-20:0":{"b": ["قتیبہ بن مسلم نے بخارا کو اپنی تحویل میں لیا", "38427fbf"], "d": ["قتیبہ دو ناکام مہمات کے بعد بخارا پر چڑھا؛ شدید محاصرے کے بعد فوجی مدد، محصول اور قلعے میں مسلم محافظ بٹھانے کی شرط پر شہر اپنی تحویل میں لیا (90/708-709)؛ یہ ماوراء النہر کی فتوحات کے لیے موڑ ثابت ہوا۔", "6b255806"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0714-01-01:0":{"b": ["مسلمہ بن عبدالملک نے درۂ Derbend پر قبضہ کیا", "839bbcf7"], "d": ["خزروں کے ساتھ شدید جھڑپیں ولید اول کے زمانے میں ہوئیں؛ مسلمہ نے 708 میں بعض شہر اور قلعے فتح کیے، 714 میں درۂ Derbend پر قبضہ کیا، 717 میں قسطنطنیہ کے محاصرے کے لیے علاقے سے ہٹے تو خزروں نے جوابی کارروائی شروع کی۔", "358cd23d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0747-10-11:0":{"b": ["خارجی ابو حمزہ نے مدینہ پر قبضہ کر لیا", "36cae3e0"], "d": ["خارجی رہنما ابو حمزہ الشاری نے مکہ پر قبضہ کرنے کے بعد صفر 130 (اکتوبر 747) میں مدینہ پر قبضہ کیا۔", "b0263b26"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0748-01-15:0":{"b": ["نصر بن سیار نے خراسان کا مرکز مرو عباسی باغیوں کے لیے چھوڑ دیا", "bc7bee2d"], "d": ["اموی گورنرِ خراسان نصر کو 9 جمادی الاول 130 (15 جنوری 748) کو مرو اور جون میں نیشاپور چھوڑنا پڑا؛ 749 ختم ہونے سے پہلے عباسی فوجوں نے پورے خراسان پر کنٹرول حاصل کر لیا۔", "dd216140"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0751-01-01:0":{"b": ["Langobards نے Ravenna لے لیا: بازنطینی Exarchate ختم ہوا", "f5a42f8f"], "d": ["Langobard بادشاہ Aistulf نے 750-751 میں Ravenna پر قبضہ کیا؛ یوں Apennines کے شمال میں بازنطین کا واحد بڑا مرکز گر گیا، صرف ونیس (Venedik) اور Istria کا ایک حصہ سلطنت سے وابستہ رہا۔", "6debbee9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0756-01-01:0":{"b": ["Pippin نے Ravenna Exarchate پاپائیت کو بخش دیا", "345e02a7"], "d": ["Frank بادشاہ Pippin نے Aistulf کو شکست دے کر Ravenna Exarchate اور Pentapolis پاپائیت کو دے دیے؛ یوں Ravenna Langobards سے لے کر پاپائی ریاست کے مرکز میں شامل ہوا۔ بازنطین اس بخشش کی مخالفت نہ کر سکا۔", "285518a8"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0757-12-03:0":{"b": ["Tang فوج Luoyang میں داخل ہوئی (757): مشرقی دارالحکومت باغیوں سے واپس لے لیا گیا", "9d80b237"], "d": ["Shaanxi کے Xindian مقام پر شکست کھانے والا باغی سپہ سالار An Qingxu اور اس کے ساتھی Hebei بھاگ گئے؛ شہزادہ Guangping Luoyang میں داخل ہوا، Tianjin پل کے جنوب میں اپنی فوج کی صفیں آراستہ کیں؛ Chen Xilie اور Zhang Ji جیسے 300 سے زائد جعلی عہدیدار سفید لباس میں اپنی سزا کے منتظر رہے۔", "6194d763"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0761-08-07:0":{"b": ["عباسی سپہ سالار محمد بن اشعث نے قیروان پر قبضہ کیا", "40b80c87"], "d": ["عبدالرحمن بن رستم کو یہاں گورنر مقرر کیے جانے کے بعد شہر پر قبضہ اس محمد بن اشعث الخزاعی نے کیا جسے خلیفہ منصور نے افریقیہ اور مغرب کی گورنری پر مقرر کیا تھا (جمادی الاول 144)۔", "b5951323"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0764-01-01:0":{"b": ["خزر فوج نے تفلیس پر قبضہ کیا", "90eb05a6"], "d": ["عباسی گورنر یزید بن اسید کی بیاہی ہوئی خزر شہزادی کے زچگی میں فوت ہو جانے پر خاقان نے As-Tarhan کی کمان میں فوج بھیجی؛ 764 میں تفلیس پر قبضہ ہو گیا۔", "0f1e9c4c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0774-01-01:0":{"b": ["Pavia نے ہتھیار ڈال دیے؛ Desiderius قید ہوا؛ Charlemagne نے 'Langobards کا بادشاہ' کا لقب لیا (Langobard بادشاہت ختم)", "2de54abb"], "d": ["Charlemagne نے پوپ Hadrianus اول کی اپیل پر 773 میں الپس عبور کر کے Lombard بادشاہت میں قدم رکھا؛ جون 774 میں Pavia نے ہتھیار ڈال دیے، بادشاہ Desiderius خانقاہ بھیج دیا گیا۔ Charles نے 'Langobards کا بادشاہ' اور 'رومیوں کا Patrikios' کے القاب لیے۔", "4dbdb9e5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0775-01-01:0":{"b": ["Ligor (Nakhon Si Thammarat) کتبہ: Sriwijaya کے بادشاہ نے جزیرہ نما ملایا میں Ligor میں قیام کر کے بدھ معبد بنوائے (775)", "62e97b39"], "d": ["Wat Sema Muang کا کتبہ ظاہر کرتا ہے کہ سماٹرا کی بادشاہت نے 775 میں جزیرہ نما ملایا میں Ligor میں قدم جمائے اور Sriwijaya کے بادشاہ (غالباً Dharmasetu) نے بدھ معبد کا مجموعہ بنوایا؛ دوسرے رخ کا متن Sailendra نسب کا حوالہ دیتا ہے۔", "85396e40"]},
