"OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA:1009-01-01:0":{"b": ["لی کونگ اوان لے خاندان کے بعد تخت نشین ہوا؛ لی خاندان قائم ہوا (1009-1225)", "ec1ea1c0"], "d": ["لے ہوان کی وفات کے چار سال کے اندر راہبوں کے ہاتھوں پروان چڑھ کر ہوا لو کے دربار میں ترقی کرنے والا لی کونگ اوان بادشاہ بنا اور دربار کو ہوا لو سے دائی لا منتقل کیا۔ ٹیلر لی کونگ اوان کا دورِ حکومت 1009-1028 دیتا ہے؛ سونگ نے 1010 میں اسے باجگزار تسلیم کیا۔", "631207b0"]},
"OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA:1025-01-01:0":{"b": ["چولا بادشاہ راجندر اول کی بحری مہم: سریویجایا (پالمبانگ)، پنائی اور کدارم (کیداہ) کی بندرگاہیں لوٹی گئیں، بادشاہ سنگرامویجایوتونگورمن قید ہوا", "7907c402"], "d": ["تنجور میں راجندر کے کتبے (1030-31) کے مطابق چولا بیڑے نے کدارم کے بادشاہ کو پکڑا، سریویجایا (پالمبانگ)، پنائی اور دوسرے مراکز کو فتح کیا/لوٹا۔ کوئدیس کے مطابق اس حملے نے سماٹرا کی سلطنت کو عارضی طور پر کمزور کیا؛ یہ کمزوری مشرقی جاوا کے واقعات پر بھی اثر انداز ہوئی۔", "ee4711ae"]},
"OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA:1087-01-01:0":{"b": ["بعد کی تین سالہ جنگ کے اختتام پر موتسو اور دیوا کیوہیرا کے ہاتھ میں متحد ہوئے؛ ہیرائیزومی میں اوشو فوجیوارا خاندان شروع ہوا", "b6b06bf9"], "d": ["میناموتو نو یوشیئے کے کیوہارا نو ایئے ہیرا کو شکست دے کر بعد کی تین سالہ جنگ (1083-87) ختم کرنے کے بعد موتسو اور دیوا کیوہارا نو کیوہیرا کے انتظام میں متحد ہوئے؛ کیوہیرا نے اپنے باپ کا فوجیوارا خاندانی نام اختیار کیا اور ہیرائیزومی کو مرکز بنایا (اوشو فوجیوارا)۔ یہ علاقہ یوریتومو کی 1189 کی فتح تک مرکزی کنٹرول سے آزاد رہا۔", "70e04e28"]},
"OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA:1113-01-01:0":{"b": ["سوریہ ورمن دوم نے دو سلطنتوں کو متحد کر کے تخت سنبھالا؛ برہمن دیواکارا نے تاج پہنایا (انگکور وات کا مستقبل کا معمار)", "d8733b04"], "d": ["کوئدیس کے مطابق سوریہ ورمن دوم نے ایک دن کی جنگ کے بعد دھرنیندر ورمن اول کو معزول کر کے «دوہری سلطنت» کو متحد کیا؛ تاج پوشی کی تقریب 1113 میں دیواکارا نے ادا کی۔ حکمران نے چین، دائی ویت اور چمپا کے خلاف بڑی مہمیں چلائیں، انگکور وات اس کے دور میں تعمیر ہوا۔", "c0d73102"]},
"OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA:1177-01-01:0":{"b": ["چام بیڑے نے میکونگ اور تونلے ساپ کے راستے انگکور پر حملہ کر کے اسے لوٹا؛ خمیر بادشاہ تری بھوانادتیہ مارا گیا", "4463a39b"], "d": ["خشکی کی مہم میں ناکام رہنے والے چام بادشاہ جیہ اندر ورمن نے 1177 میں سمندر سے حملہ کیا؛ ایک چینی بچ جانے والے کی رہنمائی سے میکونگ کے دہانے اور وہاں سے بڑی جھیل (تونلے ساپ) پہنچنے والے بیڑے نے انگکور پر اچانک حملہ کر کے اسے لوٹا۔ بیس سالہ اندرونی انتشار کے بعد آنے والی اس آفت نے خمیر سلطنت کو ہلا کر رکھ دیا۔", "5aab1448"]},
"OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA:1181-01-01:0":{"b": ["جے ورمن ہفتم چام حملے کے چار سال بعد تخت نشین ہوا؛ انگکور کو فصیل اور خندق سے گھیر کر دوبارہ تعمیر کیا (انگکور تھوم)", "c7ebfaa5"], "d": ["1177 کے حملے کو شکست دے کر ملک کو سنبھالنے والے جے ورمن ہفتم نے 1181 میں تاج پہنا اور دارالحکومت کو موجودہ انگکور تھوم کی خندق اور فصیل کے ساتھ دوبارہ تعمیر کیا۔ اس کا دورِ حکومت (1181-تقریباً 1220) خمیر ریاست کی وسیع ترین حدود کا دور ہے؛ چمپا کا الحاق اسی دور میں ہوا۔", "6091412c"]},
"OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA:1185-01-01:0":{"b": ["گنپے جنگ کا 1185 میں میناموتو کی فتح پر اختتام: کاماکورا کی عسکری حکومت (باکوفو) ملک گیر اقتدار میں بدل گئی", "1ec6a451"], "d": ["میناموتو نو یوریتومو نے 1180 میں کاماکورا کو اڈہ بنایا تھا؛ گنپے جنگ (1180-85) جیتنے پر کاماکورا عملی اقتدار رکھنے والی عسکری انتظامیہ کا مرکز بن گیا۔", "07998c57"]},
"OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA:1185-12-21:0":{"b": ["بونجی کی سند: ہوجو توکیماسا کی درخواست پر دربار نے یوریتومو کو ملک بھر میں شوگو اور جیتو مقرر کرنے کا اختیار دیا (بونجی 1/11/28)", "898d894e"], "d": ["یوشیتسونے کے یوریتومو کے خلاف کھڑے ہونے کے بعد دسمبر 1185 کے آخر میں دربار نے ہوجو توکیماسا کی درخواست پر کاماکورا کو ہر صوبے میں شوگو (عسکری-پولیس گورنر) اور جیتو (زمین/ٹیکس منتظم) مقرر کرنے اور معزول کرنے کا اختیار دیا۔ یہ وہ لمحہ سمجھا جاتا ہے جب باکوفو نے صوبوں میں مستقل انتظامی اختیار پایا (بونجی کونی-جیتو)۔ (کیوشو: شوگو/جیتو کے نفاذ کا علاقہ۔)", "6158cfad"]},
