"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1202-01-01:0":{"b": ["محمد بختیار خلجی نے سین کا دارالحکومت لے کر نادیا کو بھی شامل کرنے والی خلجی سلطنت کی بنیاد رکھی", "3cdd7eb4"], "d": ["غوری سپہ سالار ایبک کے ماتحت محمد بختیار خلجی نے ہندو سین خاندان کا دارالحکومت لکھنوتی فتح کیا؛ اسے مرکز بنا کر دیوکوٹ، نادیا اور بنگ کو شامل کرنے والے خلجی خاندان کی بنیاد رکھی (1202)۔ بہار 1193 میں پہلے ہی خلجیوں کے قبضے میں آ چکا تھا۔", "ab8df366"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1206-01-01:0":{"b": ["قطب الدین ایبک نے دہلی سلطنت قائم کی؛ غوری معز الدین کی وفات سے آزاد سلطنت وجود میں آئی", "9a5f76ff"], "d": ["غوری سلطان معز الدین محمد بن سام کے 1206 میں قتل کے بعد ترک سپہ سالار قطب الدین ایبک تخت نشین ہوا اور ہندوستان میں غوری علاقے ایک آزاد سلطنت بن گئے (مملوک/غلام خاندان)۔ سلطنت کا حقیقی بانی اس کا داماد التتمش سمجھا جاتا ہے۔", "24a308ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1206-01-01:1":{"b": ["محمد بختیار خلجی کا انتقال؛ عز الدین محمد جانشین ہوا", "29c4f215"], "d": ["کامروپ-تبت مہم سے بھاری نقصان کے ساتھ لوٹنے والے محمد بختیار غم سے بیمار ہو کر فوت ہوئے، ایک اور روایت کے مطابق علی مردان نامی امیر کے ہاتھوں قتل ہوئے (1206)؛ سپہ سالاروں کی حمایت سے عز الدین محمد جانشین ہوا۔", "a94f13eb"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1206-06-25:0":{"b": ["قطب الدین ایبک لاہور میں تخت نشین ہوا؛ غوری حکمران نے اسے سلطان کا لقب دیا", "19e0fcf3"], "d": ["غوری معز الدین کی وفات پر ایبک «قطب الدین» کے لقب سے لاہور میں تخت نشین ہوا۔ غوری حکمران غیاث الدین محمود نے اس عملی صورتِ حال کی توثیق کر کے اسے سلطان کا لقب اور سلطنت کی علامت کے طور پر چھتر بھیجا۔ ایبک کے دور میں سلطنت کی حدود پنجاب سے بہار تک اور کشمیر سے وسطی ہندوستانی سطح مرتفع تک پھیل گئیں۔", "e4cb6f45"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1208-07-16:0":{"b": ["قطب الدین ایبک نے لاہور میں یلدز کو شکست دے کر غزنی میں داخلہ لیا؛ یلدز نے غزنی واپس لے لیا", "0624f89b"], "d": ["ایبک کے سب سے خطرناک حریف غوری امیر تاج الدین یلدز اور ناصر الدین قباچہ تھے۔ یلدز کے عہد توڑنے پر ایبک نے لاہور پر چڑھائی کر کے اسے شکست دی اور غزنی میں داخل ہوا؛ تاہم یلدز نے بعد میں غزنی دوبارہ حاصل کر لیا (1208-1209)۔", "808f1935"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1210-01-01:0":{"b": ["شکست خوردہ قراخطائی فوج دارالحکومت بالاساغون لوٹی تو عوام نے دروازے بند کر دیے؛ شہر کا محاصرہ ہوا اور تین دن لوٹا گیا", "1d86ecfb"], "d": ["خوارزم شاہ محمد بن تکش نے ایلاماش کے میدان میں قراخطائی سپہ سالار تایانگو کی فوج کو شکست دی اور اسے قید کر لیا۔ بے سہارا فوج دارالحکومت بالاساغون لوٹی تو اہلِ شہر نے قلعے کے دروازے بند کر دیے؛ محاصرے میں آیا ہوا شہر تین دن لوٹا گیا اور عوام کا قتلِ عام ہوا۔ قراخطائی ایک سال بعد نایمان کوچلک کے ہاتھوں ختم ہونے والے تھے۔", "abc6f37b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1210-11-04:0":{"b": ["قطب الدین ایبک چوگان کھیلتے ہوئے گھوڑے سے گر کر فوت ہوا؛ لاہور میں دفن ہوا", "49253cb4"], "d": ["دہلی سلطنت کا بانی قطب الدین ایبک اپنے پسندیدہ چوگان کے کھیل کے دوران گھوڑے سے گر کر فوت ہوا اور لاہور میں دفن ہوا (1210)۔ اس کا داماد التتمش جانشین ہوا (1211)۔", "3c45bec0"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1213-01-01:0":{"b": ["خلجی سپہ سالاروں نے علاء الدین علی کو قتل کیا؛ غیاث الدین خلجی لکھنوتی کا سلطان بنا", "c4db6f56"], "d": ["عز الدین کی 1211 میں وفات پر علاء الدین کے لقب سے علی جانشین ہوا؛ ذہنی توازن بگڑنے پر خلجی سپہ سالاروں نے اسے ہٹا دیا (1213)۔ لکھنوتی کے خلجیوں کے آخری حکمران غیاث الدین خلجی نے گنگا اور برہمپترا کے سیلابوں کے خلاف ایک بڑا بند بنوایا۔", "40a8748f"]},
